        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --text: #132238;
        --muted: #5f6b85;
        --border: #d9e2f0;
        --accent: #4f7cff;
        --accent-soft: #edf2ff;
        --shadow: 0 18px 50px rgba(19, 34, 56, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, #ffffff 0, #f4f7fb 42%, #eaf0f9 100%);
        color: var(--text);
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .page {
        width: min(100%, 720px);
      }

      .card {
        background: var(--surface);
        border: 1px solid rgba(217, 226, 240, 0.9);
        border-radius: 24px;
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .card-header {
        padding: 32px 32px 20px;
        border-bottom: 1px solid var(--border);
        background: linear-gradient(180deg, #fbfcff 0%, #ffffff 100%);
      }

      .eyebrow {
        display: inline-block;
        font-size: 12px;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--accent);
        background: var(--accent-soft);
        border-radius: 999px;
        padding: 8px 12px;
        margin-bottom: 16px;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.65rem, 2.8vw, 2.3rem);
        line-height: 1.15;
      }

      .subtitle {
        margin: 12px 0 0;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        padding: 32px;
      }

      .form-field {
        margin-bottom: 28px;
      }

      .question {
        margin: 0 0 16px;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .choices {
        display: grid;
        gap: 12px;
      }

      .choice {
        display: flex;
        align-items: center;
        gap: 14px;
        padding: 16px 18px;
        border: 1px solid var(--border);
        border-radius: 16px;
        background: #fff;
        cursor: pointer;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      }

      .choice:hover {
        border-color: rgba(79, 124, 255, 0.5);
        box-shadow: 0 8px 24px rgba(79, 124, 255, 0.08);
        transform: translateY(-1px);
      }

      .choice input {
        width: 18px;
        height: 18px;
        accent-color: var(--accent);
        margin: 0;
      }

      .choice span {
        font-size: 1rem;
        font-weight: 600;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
      }

      .submit-button {
        appearance: none;
        border: 0;
        border-radius: 14px;
        padding: 14px 22px;
        background: linear-gradient(135deg, #4f7cff, #355df5);
        color: #fff;
        font-size: 1rem;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 14px 30px rgba(53, 93, 245, 0.24);
        transition: transform 0.2s ease, box-shadow 0.2s ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 36px rgba(53, 93, 245, 0.3);
      }

      .submit-button:focus-visible,
      .choice input:focus-visible {
        outline: 3px solid rgba(79, 124, 255, 0.28);
        outline-offset: 3px;
      }

      .footer-note {
        margin-top: 14px;
        color: var(--muted);
        font-size: 0.92rem;
      }

      @media (max-width: 640px) {
        .card-header,
        form {
          padding: 22px;
        }

        .actions {
          justify-content: stretch;
        }

        .submit-button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
