              e(
                "div",
                { className: "form-field" },
                e("p", { className: "question" }, "How do you prefer to receive notifications?"),
                e(
                  "div",
                  { className: "choices", role: "radiogroup", "aria-label": "Notification preference" },
                  e(RadioOption, {
